import * as OurStringification from "../src/stringification";
import * as OurTypes from "../src/types";

test("RecorD stringification round-trip Ok", () => {
  const literal = OurTypes.RecorD.Ok;

  const text = OurStringification.mustRecordToString(literal);
  expect(text).toStrictEqual("ok");

  const nullableText = OurStringification.recordToString(literal);
  expect(nullableText).toStrictEqual("ok");

  const parsed = OurStringification.recordFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("RecorD stringification round-trip NotOk", () => {
  const literal = OurTypes.RecorD.NotOk;

  const text = OurStringification.mustRecordToString(literal);
  expect(text).toStrictEqual("not-ok");

  const nullableText = OurStringification.recordToString(literal);
  expect(nullableText).toStrictEqual("not-ok");

  const parsed = OurStringification.recordFromString(text);
  expect(parsed).toStrictEqual(literal);
});

test("RecorD from invalid string", () => {
  const parsed = OurStringification.recordFromString(
    "invalid-literal"
  );

  expect(parsed).toBeNull();
});

test("RecorD invalid literal to string", () => {
  // The number 9007199254740991 is the maximum safe integer.
  const invalidLiteral = <OurTypes.RecorD>9007199254740991;

  expect(OurStringification.recordToString(invalidLiteral)).toBeNull();
  expect(() => OurStringification.mustRecordToString(invalidLiteral)).toThrow();
});

